css:
/* Create the Improbable — Creative-atelier theme: warm paper, ink, vivid creative magenta/violet accents. */
.improb-sim-container {
    padding: 28px;
    background: #f4efe7;
    background-image: radial-gradient(circle at 12% 8%, rgba(214,51,132,0.06) 0, transparent 45%), radial-gradient(circle at 92% 96%, rgba(101,75,196,0.07) 0, transparent 50%);
    min-height: 100vh;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    color: #211c2b;
}
.improb-sim-header {
    background: linear-gradient(135deg, #1b1726 0%, #2c2340 100%);
    color: #f7f3ff;
    padding: 34px 38px;
    border-radius: 10px;
    margin-bottom: 24px;
    border-left: 6px solid #d63384;
    box-shadow: 0 12px 34px rgba(43,35,64,0.28);
    position: relative;
    overflow: hidden;
}
.improb-sim-header::after {
    content: "";
    position: absolute;
    top: -40px;
    right: -30px;
    width: 220px;
    height: 220px;
    background: radial-gradient(circle, rgba(214,51,132,0.30) 0, transparent 70%);
    pointer-events: none;
}
.improb-sim-header-tag {
    display: inline-block;
    background: rgba(214,51,132,0.22);
    color: #ff9ecb;
    padding: 5px 13px;
    border-radius: 20px;
    font-size: 0.73rem;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    margin-bottom: 14px;
    font-weight: 700;
    position: relative;
}
.improb-sim-header h1 {
    font-size: 2.15rem;
    font-weight: 800;
    margin: 0 0 10px 0;
    letter-spacing: -0.02em;
    position: relative;
}
.improb-sim-subtitle {
    margin: 0;
    font-size: 1.02rem;
    color: #cfc4e6;
    max-width: 780px;
    line-height: 1.55;
    position: relative;
}
.improb-sim-period-counter {
    background: #ffffff;
    border: 1px solid #e4dccf;
    border-radius: 10px;
    padding: 14px 22px;
    margin-bottom: 24px;
    font-size: 0.95rem;
    color: #6f667e;
    font-weight: 500;
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    box-shadow: 0 4px 14px rgba(43,35,64,0.06);
}
.improb-sim-period-counter span {
    font-weight: 700;
    color: #211c2b;
}
.improb-sim-round-name {
    margin-left: 14px;
    color: #654bc4;
    text-transform: uppercase;
    letter-spacing: 0.06em;
    font-size: 0.85rem;
}
.improb-sim-clock {
    margin-left: auto;
    color: #d63384 !important;
    font-variant-numeric: tabular-nums;
    background: rgba(214,51,132,0.12);
    padding: 4px 12px;
    border-radius: 20px;
    font-size: 0.85rem;
}
.improb-sim-status-cards {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(210px, 1fr));
    gap: 16px;
    margin-bottom: 24px;
}
.improb-sim-status-card {
    background: #ffffff;
    border: 1px solid #e4dccf;
    border-radius: 10px;
    padding: 22px 20px;
    transition: transform 0.2s ease, box-shadow 0.2s ease;
    box-shadow: 0 4px 14px rgba(43,35,64,0.06);
}
.improb-sim-status-card:hover {
    transform: translateY(-3px);
    box-shadow: 0 12px 26px rgba(43,35,64,0.14);
}
.improb-sim-card-primary {
    border-top: 4px solid #d63384;
    background: linear-gradient(180deg, #fff3f9 0%, #ffffff 100%);
}
.improb-sim-card-budget {
    border-top: 4px solid #654bc4;
    background: linear-gradient(180deg, #f4f1ff 0%, #ffffff 100%);
}
.improb-sim-label {
    color: #8a7f9b;
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    font-weight: 700;
    margin-bottom: 10px;
}
.improb-sim-value {
    font-size: 2.5rem;
    font-weight: 800;
    color: #211c2b;
    line-height: 1;
    margin-bottom: 6px;
    font-variant-numeric: tabular-nums;
}
.improb-sim-card-primary .improb-sim-value {
    color: #d63384;
}
.improb-sim-card-budget .improb-sim-value {
    color: #654bc4;
    font-size: 2.1rem;
}
.improb-sim-sublabel {
    color: #9a8fab;
    font-size: 0.78rem;
    line-height: 1.35;
}
.improb-sim-briefing {
    background: #ffffff;
    border: 1px solid #efd9cf;
    border-left: 5px solid #e8893b;
    border-radius: 10px;
    padding: 22px 24px;
    margin-bottom: 24px;
    display: flex;
    gap: 18px;
    align-items: flex-start;
    box-shadow: 0 4px 14px rgba(43,35,64,0.06);
}
.improb-sim-briefing-icon {
    font-size: 2rem;
    line-height: 1;
    flex-shrink: 0;
}
.improb-sim-briefing-body {
    flex: 1;
}
.improb-sim-briefing-title {
    font-size: 1.12rem;
    font-weight: 800;
    color: #b85c12;
    margin-bottom: 8px;
}
.improb-sim-briefing-text {
    color: #3c3548;
    line-height: 1.62;
    font-size: 0.96rem;
}
.improb-sim-briefing-text strong {
    color: #b85c12;
}
.improb-sim-controls {
    background: #ffffff;
    border: 1px solid #e4dccf;
    border-radius: 10px;
    padding: 26px;
    margin-bottom: 24px;
    box-shadow: 0 4px 14px rgba(43,35,64,0.06);
}
.improb-sim-controls h3 {
    font-size: 1.12rem;
    font-weight: 800;
    color: #211c2b;
    margin: 0 0 18px 0;
    padding-bottom: 12px;
    border-bottom: 1px solid #ece4d8;
}
.improb-sim-panel {
    margin-bottom: 8px;
}
.improb-sim-controls label {
    display: block;
    font-size: 0.86rem;
    font-weight: 600;
    color: #4b4358;
    margin-bottom: 6px;
    margin-top: 16px;
}
.improb-sim-controls input[type="number"],
.improb-sim-controls input[type="text"],
.improb-sim-controls select {
    width: 100%;
    background-color: #faf7f1;
    border: 1px solid #d9cfc0;
    color: #211c2b;
    border-radius: 6px;
    padding: 10px 12px;
    font-size: 0.95rem;
    font-family: inherit;
    transition: border-color 0.2s ease, box-shadow 0.2s ease;
}
.improb-sim-controls select option {
    background-color: #ffffff;
    color: #211c2b;
}
.improb-sim-controls input[type="number"]:focus,
.improb-sim-controls input[type="text"]:focus,
.improb-sim-controls select:focus {
    outline: none;
    border-color: #d63384;
    box-shadow: 0 0 0 3px rgba(214,51,132,0.16);
}
.improb-sim-controls input[type="range"] {
    width: 100%;
    accent-color: #d63384;
    margin-top: 8px;
}
.improb-sim-range-readout {
    font-size: 0.85rem;
    color: #6f667e;
    margin-top: 6px;
}
.improb-sim-range-readout span:last-child {
    color: #d63384;
    font-weight: 800;
}
.improb-sim-controls .btn {
    margin-top: 24px;
    padding: 12px 26px;
    border-radius: 6px;
    font-weight: 700;
    font-size: 0.95rem;
    letter-spacing: 0.02em;
    border: none;
    transition: background 0.2s ease, transform 0.15s ease;
}
.improb-sim-controls .btn-primary {
    background: #d63384;
    color: #ffffff;
}
.improb-sim-controls .btn-primary:hover {
    background: #e84a99;
    transform: translateY(-1px);
}
.improb-sim-controls .btn-outline-secondary {
    background: transparent;
    color: #6f667e;
    border: 1px solid #d9cfc0;
    margin-left: 10px;
}
.improb-sim-controls .btn-outline-secondary:hover {
    background: #f4efe7;
    color: #211c2b;
}
.improb-sim-coach {
    background: linear-gradient(135deg, #2c2340 0%, #3d3057 100%);
    color: #f0eafa;
    border-radius: 10px;
    padding: 22px 26px;
    margin-bottom: 24px;
    border-left: 5px solid #d63384;
    box-shadow: 0 8px 24px rgba(43,35,64,0.2);
}
.improb-sim-coach-header {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 0.14em;
    color: #ff9ecb;
    font-weight: 800;
    margin-bottom: 10px;
}
.improb-sim-coach-body {
    line-height: 1.62;
    font-size: 0.98rem;
    color: #f0eafa;
}
.improb-sim-coach-body strong {
    color: #ffc4e1;
}
.improb-sim-history {
    background: #ffffff;
    border: 1px solid #e4dccf;
    border-radius: 10px;
    padding: 24px;
    margin-bottom: 24px;
    overflow-x: auto;
    box-shadow: 0 4px 14px rgba(43,35,64,0.06);
}
.improb-sim-history h3 {
    font-size: 1.05rem;
    font-weight: 800;
    color: #211c2b;
    margin: 0 0 14px 0;
}
.improb-sim-history table {
    margin-bottom: 0;
    color: #3c3548;
    width: 100%;
}
.improb-sim-history table th {
    background: #faf7f1;
    color: #8a7f9b;
    font-size: 0.76rem;
    text-transform: uppercase;
    letter-spacing: 0.06em;
    font-weight: 700;
    border-bottom: 2px solid #ece4d8;
    padding: 10px 12px;
}
.improb-sim-history table td {
    color: #3c3548;
    font-size: 0.9rem;
    padding: 10px 12px;
    border-bottom: 1px solid #f0ebe1;
}
.improb-sim-chart {
    background: #ffffff;
    border: 1px solid #e4dccf;
    border-radius: 10px;
    padding: 24px;
    margin-bottom: 24px;
    height: 380px;
    box-shadow: 0 4px 14px rgba(43,35,64,0.06);
}
.improb-sim-chart h3 {
    font-size: 1.05rem;
    font-weight: 800;
    color: #211c2b;
    margin: 0 0 14px 0;
}
.improb-sim-chart canvas {
    max-height: 300px;
}
@media (max-width: 768px) {
    .improb-sim-container { padding: 16px; }
    .improb-sim-header { padding: 24px 22px; }
    .improb-sim-header h1 { font-size: 1.55rem; }
    .improb-sim-status-cards { grid-template-columns: repeat(2, 1fr); }
    .improb-sim-value { font-size: 1.9rem; }
    .improb-sim-card-budget .improb-sim-value { font-size: 1.6rem; }
    .improb-sim-period-counter { flex-wrap: wrap; }
    .improb-sim-clock { margin-left: 0; width: 100%; margin-top: 6px; text-align: center; }
    .improb-sim-round-name { margin-left: 0; }
}


/* ---- v1.1.0 completion / debrief screen ---- */
.ci-completion { padding: 8px 4px 4px; color: #211c2b; }
.ci-cm-head { text-align: center; margin-bottom: 16px; }
.ci-cm-score { font-size: 3.2rem; font-weight: 800; line-height: 1; color: #d63384; }
.ci-cm-score-max { font-size: 1.2rem; font-weight: 600; color: #654bc4; }
.ci-cm-grade { font-size: 1.2rem; font-weight: 700; margin-top: 6px; color: #211c2b; }
.ci-cm-badge { display: inline-block; margin-left: 6px; padding: 2px 10px; border-radius: 999px; font-size: 0.78rem; font-weight: 700; vertical-align: middle; }
.ci-cm-yes { background: rgba(101,75,196,0.15); color: #654bc4; border: 1px solid rgba(101,75,196,0.4); }
.ci-cm-no { background: rgba(214,51,132,0.12); color: #d63384; border: 1px solid rgba(214,51,132,0.4); }
.ci-cm-metrics { display: flex; flex-wrap: wrap; gap: 10px; justify-content: center; margin: 12px 0 16px; }
.ci-cm-metric { flex: 1 1 120px; min-width: 108px; background: #faf7f1; border: 1px solid #e4dccf; border-radius: 10px; padding: 10px 8px; text-align: center; }
.ci-cm-mv { display: block; font-size: 1.4rem; font-weight: 800; color: #d63384; }
.ci-cm-ml { display: block; font-size: 0.72rem; margin-top: 4px; color: #6f667e; text-transform: uppercase; letter-spacing: 0.03em; }
.ci-cm-insights-title { font-weight: 700; margin: 8px 0 6px; color: #211c2b; }
.ci-cm-insights { margin: 0; padding-left: 20px; }
.ci-cm-insights li { margin-bottom: 8px; line-height: 1.5; font-size: 0.92rem; color: #3c3548; }

