(function() {
    'use strict';

    class ImprobableAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `Create the Improbable`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // Concept truths.
            this.START_BUDGET = 180000;        // € pitch budget
            this.CANNIBAL_LOW = 8;             // €M finance floor of honest displacement
            this.CANNIBAL_HIGH = 12;           // €M finance ceiling
            this.PROVOCATION_COST = {          // € and days drawn from the 21-day / €180k budget
                invert:     { cost: 45000, days: 4 },
                forbidden:  { cost: 55000, days: 5 },
                artefact:   { cost: 70000, days: 7 },
                brainstorm: { cost: 20000, days: 2 }
            };
            this.PROTOTYPE_COST = {
                working: 60000,
                render: 25000,
                none: 0
            };
            this.FRAME_IS_REFRAME = { ritual: true, heat: true, lighter: false, induction: false };
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    improbability: 25,
                    certainty: 30,
                    sponsor: 40,
                    budget: this.START_BUDGET,
                    daysLeft: 21,
                    reframed: false,            // did Move 1 actually change the question?
                    provocationRun: ``,
                    cannibalBooked: 0,          // €M honestly disclosed
                    destroyedSomething: false,
                    hasPrototype: false,
                    sponsorWon: ``,
                    reranProvocation: false,    // had to re-run after killing the improbable early
                    improbHistory: [25],
                    certaintyHistory: [30],
                    coachMessages: [],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    frame: `ritual`,
                    ambition: 55,
                    ownable: `high`,
                    provocation: `artefact`,
                    suspend: 60,
                    judge: `value`,
                    destroy: `cocotte`,
                    cannibal: 10,
                    prototype: `working`,
                    sponsor: `ceo`,
                    defend: `own`,
                    arc: `arc`,
                    poise: 70
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const fr = document.getElementById(`frameInput`);
                const am = document.getElementById(`ambitionInput`);
                const ow = document.getElementById(`ownableInput`);
                if (fr) decisions.frame = fr.value;
                if (ow) decisions.ownable = ow.value;
                if (am) decisions.ambition = parseInt(am.value, 10);
                if (!Number.isFinite(decisions.ambition) || decisions.ambition < 0 || decisions.ambition > 100) {
                    warn(`warn_ambition_range`); return false;
                }
            } else if (round === 2) {
                const pr = document.getElementById(`provocationInput`);
                const su = document.getElementById(`suspendInput`);
                const ju = document.getElementById(`judgeInput`);
                if (pr) decisions.provocation = pr.value;
                if (ju) decisions.judge = ju.value;
                if (su) decisions.suspend = parseInt(su.value, 10);
                if (!Number.isFinite(decisions.suspend) || decisions.suspend < 0 || decisions.suspend > 100) {
                    warn(`warn_suspend_range`); return false;
                }
            } else if (round === 3) {
                const de = document.getElementById(`destroyInput`);
                const ca = document.getElementById(`cannibalInput`);
                const pt = document.getElementById(`prototypeInput`);
                if (de) decisions.destroy = de.value;
                if (pt) decisions.prototype = pt.value;
                if (ca) decisions.cannibal = parseFloat(ca.value);
                if (!Number.isFinite(decisions.cannibal) || decisions.cannibal < 0 || decisions.cannibal > 25) {
                    warn(`warn_cannibal_range`); return false;
                }
            } else if (round === 4) {
                const sp = document.getElementById(`sponsorInput`);
                const df = document.getElementById(`defendInput`);
                const ar = document.getElementById(`arcInput`);
                const po = document.getElementById(`poiseInput`);
                if (sp) decisions.sponsor = sp.value;
                if (df) decisions.defend = df.value;
                if (ar) decisions.arc = ar.value;
                if (po) decisions.poise = parseInt(po.value, 10);
                if (!Number.isFinite(decisions.poise) || decisions.poise < 0 || decisions.poise > 100) {
                    warn(`warn_poise_range`); return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            let improbDelta = 0, certaintyDelta = 0, sponsorDelta = 0;
            let spend = 0, daysSpent = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // Reframe precedes ideation. A line extension is the brief the CEO already rejected.
                daysSpent = 3;
                const isReframe = !!this.FRAME_IS_REFRAME[d.frame];
                ds.reframed = isReframe;
                if (isReframe) {
                    // Ambition lifts improbability; sweet spot is genuinely high (>=60).
                    improbDelta += 14 + Math.round((d.ambition - 40) / 5); // ~ +14 .. +26
                    sponsorDelta += 4;
                    coachKey = (d.ambition >= 60) ? `coach_r1_reframe_bold` : `coach_r1_reframe_timid`;
                    summaryKey = `sum_r1_reframe`;
                } else {
                    // Common Error 1: polishing instead of reframing -> the rejected brief.
                    improbDelta -= 14;
                    sponsorDelta -= 10;
                    coachKey = `coach_r1_lineext`;
                    summaryKey = `sum_r1_lineext`;
                }
                // Ownability is the defensibility of the new category (certainty + a little improbability moat).
                if (d.ownable === `high`) { certaintyDelta += 8; improbDelta += 4; }
                else if (d.ownable === `med`) { certaintyDelta += 3; }
                else { certaintyDelta -= 4; improbDelta -= 2; }
            } else if (round === 2) {
                // Run a provocation; suspend feasibility; judge on value not next quarter.
                const prov = this.PROVOCATION_COST[d.provocation] || this.PROVOCATION_COST.brainstorm;
                spend += prov.cost;
                daysSpent += prov.days;
                ds.provocationRun = d.provocation;

                // Disruptive provocations generate improbable ideas; a normal brainstorm generates novelty at best.
                if (d.provocation === `artefact`) { improbDelta += 18; certaintyDelta += 4; }
                else if (d.provocation === `forbidden`) { improbDelta += 16; }
                else if (d.provocation === `invert`) { improbDelta += 14; }
                else { improbDelta += 3; certaintyDelta += 2; } // brainstorm: safe

                // Common Error 3: killing the improbable too early by judging on next-quarter sales.
                // The provocation only works if feasibility is suspended during divergence.
                let strangled = false;
                if (d.judge === `quarter` || d.judge === `vote` || d.suspend < 40) {
                    strangled = true;
                }
                if (strangled) {
                    // The improbable is filtered out before it can be judged on value -> rerun the provocation.
                    improbDelta = Math.round(improbDelta * 0.35) - 4;
                    ds.reranProvocation = true;
                    spend += 15000; // wasted spend re-running
                    daysSpent += 2;
                    coachKey = `coach_r2_strangled`;
                    summaryKey = `sum_r2_strangled`;
                } else {
                    coachKey = (d.provocation === `brainstorm`) ? `coach_r2_brainstorm` : `coach_r2_good`;
                    summaryKey = (d.provocation === `brainstorm`) ? `sum_r2_safe` : `sum_r2_good`;
                }
                // A reframed brief amplifies what the provocation can produce.
                if (!ds.reframed) {
                    improbDelta = Math.round(improbDelta * 0.6);
                }
            } else if (round === 3) {
                // Creative destruction + honest cannibalisation + a deliverable prototype.
                daysSpent += 4;
                spend += this.PROTOTYPE_COST[d.prototype] || 0;

                // Common Error 2: novel-but-safe, destroys nothing.
                if (d.destroy === `nothing`) {
                    ds.destroyedSomething = false;
                    improbDelta -= 12;
                    sponsorDelta -= 6;
                    coachKey = `coach_r3_nodestroy`;
                    summaryKey = `sum_r3_nodestroy`;
                } else {
                    ds.destroyedSomething = true;
                    improbDelta += 12;
                    if (d.destroy === `cocotte`) improbDelta += 4;       // killing the heritage SKU is the boldest
                    else if (d.destroy === `margin`) certaintyDelta += 2;
                    summaryKey = `sum_r3_destroy`;
                }

                // Common Error 4: hiding the cannibalisation. Booking inside €8–12M earns board trust.
                ds.cannibalBooked = d.cannibal;
                if (ds.destroyedSomething) {
                    if (d.cannibal >= this.CANNIBAL_LOW && d.cannibal <= this.CANNIBAL_HIGH) {
                        sponsorDelta += 12; // honest accounting boards forgive
                        certaintyDelta += 4;
                        coachKey = `coach_r3_honest`;
                    } else if (d.cannibal < this.CANNIBAL_LOW) {
                        sponsorDelta -= 12; // understating it = hiding it
                        coachKey = `coach_r3_understate`;
                        summaryKey = `sum_r3_hidden`;
                    } else {
                        sponsorDelta -= 4; // overstating spooks the room and dents the value case
                        coachKey = `coach_r3_overstate`;
                    }
                }

                // Common Error 5 origin: certainty comes from a real prototype + proof points.
                if (d.prototype === `working`) {
                    certaintyDelta += 20; ds.hasPrototype = true;
                    if (coachKey === `coach_default`) coachKey = `coach_r3_prototype`;
                } else if (d.prototype === `render`) {
                    certaintyDelta += 6; ds.hasPrototype = false;
                } else {
                    certaintyDelta -= 8; ds.hasPrototype = false;
                }
            } else if (round === 4) {
                // The pitch: sponsor won before the room, defend cannibalisation, tell the arc, stay composed.
                daysSpent += Math.max(0, ds.daysLeft); // the remaining runway is consumed up to the pitch
                ds.sponsorWon = d.sponsor;

                // Common Error 6: no internal sponsor -> walk in cold.
                if (d.sponsor === `none`) {
                    sponsorDelta -= 16;
                    coachKey = `coach_r4_nosponsor`;
                    summaryKey = `sum_r4_nosponsor`;
                } else {
                    sponsorDelta += 14;
                    if (d.sponsor === `chair`) sponsorDelta += 6; // co-opting the hostile chair is the masterstroke
                    summaryKey = `sum_r4_sponsor`;
                }

                // Defending the cannibalisation.
                if (d.defend === `own`) {
                    sponsorDelta += 10; certaintyDelta += 4;
                    if (coachKey === `coach_default`) coachKey = `coach_r4_own`;
                } else if (d.defend === `hide`) {
                    sponsorDelta -= 14; // finance puts up the slide; trust collapses
                    coachKey = `coach_r4_hide`;
                } else {
                    // Retreating to protect the Cocotte talks you back into a line extension.
                    improbDelta -= 14; sponsorDelta += 2;
                    coachKey = `coach_r4_retreat`;
                    summaryKey = `sum_r4_retreat`;
                }

                // The narrative arc: improbable must feel both desirable and inevitable.
                if (d.arc === `arc`) { improbDelta += 6; certaintyDelta += 6; sponsorDelta += 4; }
                else if (d.arc === `vision`) { improbDelta += 3; certaintyDelta -= 6; } // vision without delivery
                else if (d.arc === `numbers`) { certaintyDelta += 3; improbDelta -= 6; sponsorDelta -= 2; }

                // Composure under the two scripted challenges.
                sponsorDelta += Math.round((d.poise - 60) / 6);
            }

            // Apply spend / time.
            ds.budget = Math.max(0, ds.budget - spend);
            ds.daysLeft = Math.max(0, ds.daysLeft - daysSpent);

            // Budget pressure: blowing the €180k budget signals you can't deliver with certainty.
            if (ds.budget <= 0 && spend > 0) {
                certaintyDelta -= 8;
                if (coachKey === `coach_default`) coachKey = `coach_overbudget`;
            }

            // Apply deltas, clamped 0..100.
            ds.improbability = Math.max(0, Math.min(100, ds.improbability + improbDelta));
            ds.certainty = Math.max(0, Math.min(100, ds.certainty + certaintyDelta));
            ds.sponsor = Math.max(0, Math.min(100, ds.sponsor + sponsorDelta));

            ds.improbHistory.push(ds.improbability);
            ds.certaintyHistory.push(ds.certainty);

            // Expose composite to the reporting/grading layer every period (results_utils.php reads
            // domainState.performance.overallScore); the R4 value is the authoritative final score.
            ds.performance = { overallScore: this._composite(ds) };

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            ds.coachMessages.push(coachMsg);
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            return {
                period: state.currentPeriod,
                improbability: ds.improbability,
                improbDelta: improbDelta,
                certainty: ds.certainty,
                certaintyDelta: certaintyDelta,
                sponsor: ds.sponsor,
                sponsorDelta: sponsorDelta,
                budget: ds.budget,
                daysLeft: ds.daysLeft,
                cannibalBooked: ds.cannibalBooked,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
        }

