        // Shared composite (0-100). Single source of truth for the per-period score written
        // to domainState.performance.overallScore (reporting/grading layer) AND the debrief.
        // Weights unchanged from v1.0.0: improbability 0.40, certainty 0.35, sponsor 0.25.
        _composite(ds) {
            return Math.max(0, Math.min(100, Math.round(
                (ds.improbability || 0) * 0.4 + (ds.certainty || 0) * 0.35 + (ds.sponsor || 0) * 0.25
            )));
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const improb = ds.improbability, certainty = ds.certainty, sponsor = ds.sponsor;

            // Art Thinking = the improbable WITH certainty. The pitch lands only when both are high AND the room defends you.
            const honest = ds.destroyedSomething && ds.cannibalBooked >= this.CANNIBAL_LOW && ds.cannibalBooked <= this.CANNIBAL_HIGH;
            const funded = improb >= 60 && certainty >= 60 && sponsor >= 55;
            const composite = this._composite(ds);

            const T = (window.mySimulation && typeof window.mySimulation.t === 'function')
                ? function(k, v) { return window.mySimulation.t(k, v); }
                : function(k) { return k; };

            // Grade band -> localized label (thresholds identical to v1.0.0).
            let performanceKey = `grade_shut`;
            if (funded && composite >= 72 && honest) performanceKey = `grade_funded`;
            else if (improb >= 55 && certainty >= 55) performanceKey = `grade_credible`;
            else if (improb < 45 && ds.reframed === false) performanceKey = `grade_lineext`;
            else if (composite >= 45) performanceKey = `grade_stalled`;
            const performance = T(performanceKey);

            const insights = [];
            if (funded && honest) {
                insights.push(window.mySimulation.t(`insight_funded`));
            } else if (improb >= 60 && certainty < 50) {
                insights.push(window.mySimulation.t(`insight_noproof`));
            } else if (improb < 45) {
                insights.push(window.mySimulation.t(`insight_lineext`));
            } else {
                insights.push(window.mySimulation.t(`insight_stalled`));
            }
            if (!ds.reframed) insights.push(window.mySimulation.t(`insight_noreframe`));
            if (!ds.destroyedSomething) insights.push(window.mySimulation.t(`insight_nodestroy`));
            if (ds.destroyedSomething && (ds.cannibalBooked < this.CANNIBAL_LOW)) insights.push(window.mySimulation.t(`insight_hidden`));
            if (!ds.hasPrototype) insights.push(window.mySimulation.t(`insight_noprototype`));
            if (ds.reranProvocation) insights.push(window.mySimulation.t(`insight_strangled`));
            if (ds.sponsorWon === `none`) insights.push(window.mySimulation.t(`insight_nosponsor`));

            return {
                improbability: improb,
                certainty: certainty,
                sponsor: sponsor,
                budget: ds.budget,
                cannibalBooked: ds.cannibalBooked,
                composite: composite,
                totalScore: composite,
                overallScore: composite,
                performanceKey: performanceKey,
                performance: performance,
                funded: funded,
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            const T = (window.mySimulation && typeof window.mySimulation.t === 'function')
                ? function(k, v) { return window.mySimulation.t(k, v); }
                : function(k) { return k; };
            const s = summary || {};
            const score = (typeof s.totalScore === 'number') ? s.totalScore
                : (typeof s.composite === 'number' ? s.composite : 0);
            const grade = s.performance || (s.performanceKey ? T(s.performanceKey) : '');
            const budget = Math.max(0, Math.round(s.budget || 0));
            const fundedBadge = s.funded
                ? '<span class="ci-cm-badge ci-cm-yes">' + T('cm_funded') + '</span>'
                : '<span class="ci-cm-badge ci-cm-no">' + T('cm_notfunded') + '</span>';
            const insights = Array.isArray(s.insights) ? s.insights : [];
            const items = insights.map(function(t){ return '<li>' + t + '</li>'; }).join('');
            const metrics = ''
                + '<div class="ci-cm-metric"><span class="ci-cm-mv">' + (s.improbability||0) + '</span><span class="ci-cm-ml">' + T('cm_m_improb') + '</span></div>'
                + '<div class="ci-cm-metric"><span class="ci-cm-mv">' + (s.certainty||0) + '</span><span class="ci-cm-ml">' + T('cm_m_cert') + '</span></div>'
                + '<div class="ci-cm-metric"><span class="ci-cm-mv">' + (s.sponsor||0) + '</span><span class="ci-cm-ml">' + T('cm_m_sponsor') + '</span></div>'
                + '<div class="ci-cm-metric"><span class="ci-cm-mv">\u20ac' + budget.toLocaleString('fr-FR') + '</span><span class="ci-cm-ml">' + T('cm_m_budget') + '</span></div>';
            return ''
                + '<div class="ci-completion">'
                +   '<div class="ci-cm-head">'
                +     '<div class="ci-cm-score">' + score + '<span class="ci-cm-score-max">/100</span></div>'
                +     '<div class="ci-cm-grade">' + grade + ' ' + fundedBadge + '</div>'
                +   '</div>'
                +   '<div class="ci-cm-metrics">' + metrics + '</div>'
                +   '<div class="ci-cm-insights-title">' + T('cm_debrief') + '</div>'
                +   '<ul class="ci-cm-insights">' + items + '</ul>'
                + '</div>';
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (!ds.reframed && state.currentPeriod >= 1) return window.mySimulation.t(`hint_reframe`);
            if (ds.reranProvocation) return window.mySimulation.t(`hint_strangled`);
            if (state.currentPeriod >= 3 && !ds.destroyedSomething) return window.mySimulation.t(`hint_destroy`);
            if (state.currentPeriod >= 3 && !ds.hasPrototype) return window.mySimulation.t(`hint_prototype`);
            if (ds.improbability >= 65 && ds.certainty >= 60) return window.mySimulation.t(`hint_strong`);
            return null;
        }

